insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'social-psychology', 'Social psychology', 'Social psychology is the methodical study of how thoughts, feelings, and behaviors are influenced by the actual, imagined, or implied presence of others. Although studying many of the same substantive topics as its counterpart in the field of sociology, psychological social psychology places more emphasis on the individual, rather than society; the influence of social structure and culture on individual outcomes, such as personality, behavior, and one''s position in social hierarchies. It also depends more heavily on experimental and laboratory research. Social psychologists typically explain human behavior as a result of the relationship between mental states and social situations, studying the social conditions under which thoughts, feelings, and behaviors occur, and how these variables influence social interactions.', 'Wikipedia: Social psychology', 'https://en.wikipedia.org/w/index.php?title=Social_psychology&oldid=1374180313', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'social-psychology' and body = 'Social psychology is the methodical study of how thoughts, feelings, and behaviors are influenced by the actual, imagined, or implied presence of others. Although studying many of the same substantive topics as its counterpart in the field of sociology, psychological social psychology places more emphasis on the individual, rather than society; the influence of social structure and culture on individual outcomes, such as personality, behavior, and one''s position in social hierarchies. It also depends more heavily on experimental and laboratory research. Social psychologists typically explain human behavior as a result of the relationship between mental states and social situations, studying the social conditions under which thoughts, feelings, and behaviors occur, and how these variables influence social interactions.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'social-psychology', 'Social psychology: Attitudes', 'In social psychology, an attitude is a learned, global evaluation that influences thought and action. Attitudes are basic expressions of approval and disapproval or likes and dislikes. For example, enjoying chocolate ice cream or endorsing the values of a particular political party are examples of attitudes. Because multiple factors influence people in any given situation, general attitudes are not always good predictors of specific behavior. For example, a person may generally value the environment but may not recycle a plastic bottle on a given day due to specific factors. One of the most influential 20th-century attitude theories was Cognitive dissonance theory. According to this theory, attitudes must be logically consistent with each other. Noticing incongruence among one''s attitudes leads to an uncomfortable state of tension, which may motivate a change in attitudes or behavior. Research on attitudes has examined the distinction between traditional, self-reported attitudes and implicit, unconscious attitudes. Experiments using the Implicit Association Test (IAT), for instance, have found that people often demonstrate implicit bias against other races, even when their explicit responses profess impartiality. Likewise, one study found that in interracial interactions, explicit attitudes correlate with verbal behavior, while implicit attitudes correlate with nonverbal behavior. Attitudes are also involved in several other areas of the discipline, such as conformity, interpersonal attraction, social perception, and prejudice.', 'Wikipedia: Social psychology', 'https://en.wikipedia.org/w/index.php?title=Social_psychology&oldid=1374180313', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'social-psychology' and body = 'In social psychology, an attitude is a learned, global evaluation that influences thought and action. Attitudes are basic expressions of approval and disapproval or likes and dislikes. For example, enjoying chocolate ice cream or endorsing the values of a particular political party are examples of attitudes. Because multiple factors influence people in any given situation, general attitudes are not always good predictors of specific behavior. For example, a person may generally value the environment but may not recycle a plastic bottle on a given day due to specific factors. One of the most influential 20th-century attitude theories was Cognitive dissonance theory. According to this theory, attitudes must be logically consistent with each other. Noticing incongruence among one''s attitudes leads to an uncomfortable state of tension, which may motivate a change in attitudes or behavior. Research on attitudes has examined the distinction between traditional, self-reported attitudes and implicit, unconscious attitudes. Experiments using the Implicit Association Test (IAT), for instance, have found that people often demonstrate implicit bias against other races, even when their explicit responses profess impartiality. Likewise, one study found that in interracial interactions, explicit attitudes correlate with verbal behavior, while implicit attitudes correlate with nonverbal behavior. Attitudes are also involved in several other areas of the discipline, such as conformity, interpersonal attraction, social perception, and prejudice.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'social-psychology', 'Social psychology: Persuasion', 'Persuasion is an active method of influence that seeks to guide people toward adopting an attitude, idea, or behavior through rational or emotional means. Persuasion relies on appeals rather than strong pressure or coercion. The process of persuasion is influenced by numerous variables that generally fall into one of five major categories: Message: includes varying degrees of reason, emotion (e.g., fear), one-sided or two-sided arguments, and other types of informational content. Dual-process theories of persuasion (such as the elaboration likelihood model) maintain that persuasion is mediated by two separate routes: central and peripheral. Facts and results influence the central route of persuasion in longer-lasting change, but require motivation to process. The peripheral route is influenced by superficial factors (e.g., smiling, clothing) and results in shorter-lasting change, but does not require as much motivation to process.', 'Wikipedia: Social psychology', 'https://en.wikipedia.org/w/index.php?title=Social_psychology&oldid=1374180313', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'social-psychology' and body = 'Persuasion is an active method of influence that seeks to guide people toward adopting an attitude, idea, or behavior through rational or emotional means. Persuasion relies on appeals rather than strong pressure or coercion. The process of persuasion is influenced by numerous variables that generally fall into one of five major categories: Message: includes varying degrees of reason, emotion (e.g., fear), one-sided or two-sided arguments, and other types of informational content. Dual-process theories of persuasion (such as the elaboration likelihood model) maintain that persuasion is mediated by two separate routes: central and peripheral. Facts and results influence the central route of persuasion in longer-lasting change, but require motivation to process. The peripheral route is influenced by superficial factors (e.g., smiling, clothing) and results in shorter-lasting change, but does not require as much motivation to process.');
